const putBriefingResult = `-- name: PutBriefingResult :execrows
INSERT INTO briefing_results (
    project_id, manifest_hash, text, source, provider_id, model, quality_json, created_at
) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT(project_id, manifest_hash) DO UPDATE SET
    text = excluded.text,
    source = excluded.source,
    provider_id = excluded.provider_id,
    model = excluded.model,
    quality_json = excluded.quality_json,
    upgraded_at = excluded.created_at
WHERE briefing_results.source = 'fallback' AND excluded.source = 'summarizer'
`

type PutBriefingResultParams struct {
	ProjectID    string `json:"project_id"`
	ManifestHash string `json:"manifest_hash"`
	Text         string `json:"text"`
	Source       string `json:"source"`
	ProviderID   string `json:"provider_id"`
	Model        string `json:"model"`
	QualityJson  string `json:"quality_json"`
	CreatedAt    string `json:"created_at"`
}

// PutBriefingResult inserts, or upgrades a fallback to summarizer text.
func (q *Queries) PutBriefingResult(ctx context.Context, arg PutBriefingResultParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, putBriefingResult,
		arg.ProjectID,
		arg.ManifestHash,
		arg.Text,
		arg.Source,
		arg.ProviderID,
		arg.Model,
		arg.QualityJson,
		arg.CreatedAt,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const resolveBriefingTarget = `-- name: ResolveBriefingTarget :one
UPDATE briefing_targets SET
    sections_json = ?1, record_id = ?2,
    regenerate_outcome = ?3,
    revision = revision + 1, updated_at = ?4
WHERE project_id = ?5 AND profile_id = ?6
  AND target_key = ?7 AND cache_epoch = ?8
  AND (record_id IS NULL OR record_id != ?2
       OR regenerate_outcome != ?3)
RETURNING revision
`

type ResolveBriefingTargetParams struct {
	SectionsJson      string         `json:"sections_json"`
	RecordID          sql.NullString `json:"record_id"`
	RegenerateOutcome string         `json:"regenerate_outcome"`
	UpdatedAt         string         `json:"updated_at"`
	ProjectID         string         `json:"project_id"`
	ProfileID         string         `json:"profile_id"`
	TargetKey         string         `json:"target_key"`
	CacheEpoch        int64          `json:"cache_epoch"`
}

// ResolveBriefingTarget points a target at a record without touching its
// attempt; it changes nothing when the target already shows that record.
func (q *Queries) ResolveBriefingTarget(ctx context.Context, arg ResolveBriefingTargetParams) (int64, error) {
	row := q.db.QueryRowContext(ctx, resolveBriefingTarget,
		arg.SectionsJson,
		arg.RecordID,
		arg.RegenerateOutcome,
		arg.UpdatedAt,
		arg.ProjectID,
		arg.ProfileID,
		arg.TargetKey,
		arg.CacheEpoch,
	)
	var revision int64
	err := row.Scan(&revision)
	return revision, err
}

